schema_ddl:
CREATE TABLE prodotti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    prezzo NUMERIC(10, 2) NOT NULL CHECK (prezzo >= 0),
    descrizione TEXT
);

CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE CHECK (email ~* '^[A-Za-z0-9._%-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,4}$')
);

CREATE TABLE ordini_clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    quantita INT NOT NULL CHECK (quantita > 0),
    data_ordine TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    totale_riga NUMERIC(10, 2) ,
    PRIMARY KEY (cliente_id, prodotto_id, data_ordine)
);
